file.content:
/* — Variant 06 — diagnostic flow */
.capd-flow { display: grid; grid-template-columns: repeat(4, 1fr); gap: 28px; }
.capd-flow-step {
  background: var(--white); border: 1px solid var(--line); border-radius: 10px;
  padding: 12px 14px; position: relative;
}
.capd-flow-step b { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--sap-blue); letter-spacing: .08em; }
.capd-flow-step span { display: block; font-size: 13px; color: var(--ink); font-weight: 600; margin-top: 4px; }
.capd-flow-step small { display: block; font-size: 11.5px; color: var(--ink-3); margin-top: 4px; line-height: 1.4; }
.capd-flow-step:not(:last-child)::after {
  content: '→'; position: absolute; top: 50%; right: -22px;
  transform: translateY(-50%); color: var(--sap-blue); font-weight: 800;
  font-size: 18px; line-height: 1; z-index: 1; pointer-events: none;
}
@media (max-width: 720px) {
  .capd-flow { grid-template-columns: 1fr; gap: 22px; }
  .capd-flow-step:not(:last-child)::after { content: '↓'; right: 50%; top: auto; bottom: -16px; transform: translateX(50%); }
}

/* — Vertical rhythm between content blocks inside .capd panel — */
.capd > .capd-flow,
.capd > .capd-split,
.capd > .capd-tree,
.capd > .capd-quad,
.capd > .capd-phases,
.capd > .capd-sev,
.capd > .capd-vs,
.capd > .capd-chips,
.capd > .capd-flags,
.capd > .capd-combos,
.capd > .capd-esc,
.capd > .capd-modules,
.capd > .capd-term,
.capd > .agent-heads,
.capd > .modules-cloud,
.capd > .rules-list,
.capd > .setup-wrap,
.capd > .tagline-strong,
.capd > figure { margin-top: 22px; }

/* — Variant 07 — inventory tree */
.capd-tree {
  background: var(--bg); border: 1px solid var(--line);
  border-radius: 12px; padding: 14px 18px;

