}

/* — Variant 06b — vertical flowchart with mixed shapes (cylinder / diamond / rect / document) */
.capd-fc-svg {
  display: block; width: 100%; max-width: 380px; height: auto;
  margin: 4px auto 0;
  color: var(--sap-blue);
}
.capd-fc-svg .cyl-body, .capd-fc-svg .cyl-top {
  fill: var(--sap-blue-soft); stroke: var(--sap-blue); stroke-width: 1.4;
}
.capd-fc-svg .diamond {
  fill: var(--sap-yellow-soft); stroke: #E0A91A; stroke-width: 1.4;
}
.capd-fc-svg .rect {
  fill: var(--white); stroke: var(--sap-blue); stroke-width: 1.4;
}
.capd-fc-svg .doc {
  fill: var(--sap-blue-soft); stroke: var(--sap-blue); stroke-width: 1.4;
}
.capd-fc-svg .doc-fold {
  fill: none; stroke: var(--sap-blue); stroke-width: 1.4;
}
.capd-fc-svg .conn {
  stroke: var(--sap-blue); stroke-width: 1.4; fill: none;
}
.capd-fc-svg .tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9.5px; font-weight: 800;
  fill: var(--sap-blue);
  text-anchor: middle; letter-spacing: 0.12em;
}
.capd-fc-svg .title {
  font-size: 13px; font-weight: 700;
  fill: var(--ink); text-anchor: middle;
}
.capd-fc-svg .meta {
  font-size: 10.5px;
  fill: var(--ink-3); text-anchor: middle;
}

